import math

def is_pretty(m, n, alpha, k):
    return m * math.ceil(n * alpha) - n * math.floor(m * alpha) == k

def is_cool(m, n, alpha, k):
    if not is_pretty(m, n, alpha, k):
        return False
    if m > n:
        if is_pretty(m - n, n, alpha, k):
            return False
    if n > m:
        if is_pretty(m, n - m, alpha, k):
            return False
    return True

def count_cool_pairs(alpha, k, limit):
    cool_pairs = []
    for m in range(1, limit + 1):
        for n in range(1, limit + 1):
            if is_cool(m, n, alpha, k):
                cool_pairs.append((m, n))
    return cool_pairs

alpha = math.sqrt(2)
for k in range(1, 11):
    pairs = count_cool_pairs(alpha, k, 100)
    print(f"k={k}, num_cool={len(pairs)}, pairs={pairs}")

