import math

def is_pretty(m, n, alpha, k):
    return m * math.ceil(n * alpha) - n * math.floor(m * alpha) == k

def count_coprime_pretty(alpha, k, limit):
    count = 0
    for m in range(1, limit + 1):
        for n in range(1, limit + 1):
            if math.gcd(m, n) == 1 and is_pretty(m, n, alpha, k):
                count += 1
    return count

alpha = math.sqrt(2)
for k in range(1, 11):
    print(f"k={k}, coprime_pretty={count_coprime_pretty(alpha, k, 1000)}")
